-- Scope SECURITY DEFINER maintenance/payment functions to the authenticated admin's canteen.
create or replace function public.admin_delete_order_history_for_date(p_date date) returns void language plpgsql security definer set search_path=public as $$declare r record;v_days integer;v_canteen uuid:=public.current_canteen_id();begin if not public.is_admin_user() or v_canteen is null then raise exception 'Only an authorized admin can delete order history';end if;create temporary table if not exists _gocanteen_history_impact(employee_id uuid primary key,bill_month integer,bill_year integer,food_total numeric,guest_total numeric,admin_total numeric) on commit drop;truncate _gocanteen_history_impact;insert into _gocanteen_history_impact select o.employee_id,extract(month from o.ordered_for)::integer,extract(year from o.ordered_for)::integer,coalesce(sum(oi.quantity*oi.unit_price),0),coalesce(sum(case when oi.item_source='guest' then oi.quantity*oi.unit_price else 0 end),0),0 from public.orders o left join public.order_items oi on oi.order_id=o.id where o.ordered_for=p_date and o.canteen_id=v_canteen group by o.employee_id,o.ordered_for;insert into _gocanteen_history_impact(employee_id,bill_month,bill_year,food_total,guest_total,admin_total) select a.employee_id,extract(month from a.adjustment_date)::integer,extract(year from a.adjustment_date)::integer,0,0,coalesce(sum(a.amount),0) from public.employee_adjustments a where a.adjustment_date=p_date and a.canteen_id=v_canteen group by a.employee_id,a.adjustment_date on conflict(employee_id) do update set admin_total=_gocanteen_history_impact.admin_total+excluded.admin_total;delete from public.employee_adjustments where adjustment_date=p_date and canteen_id=v_canteen;delete from public.orders where ordered_for=p_date and canteen_id=v_canteen;for r in select * from _gocanteen_history_impact loop select count(distinct o.ordered_for)::integer into v_days from public.orders o where o.employee_id=r.employee_id and o.canteen_id=v_canteen and extract(month from o.ordered_for)=r.bill_month and extract(year from o.ordered_for)=r.bill_year and coalesce(o.status,'')<>'cancelled';update public.monthly_bills mb set food_total=greatest(coalesce(mb.food_total,0)-coalesce(r.food_total,0),0),guest_food_total=greatest(coalesce(mb.guest_food_total,0)-coalesce(r.guest_total,0),0),admin_added_total=greatest(coalesce(mb.admin_added_total,0)-coalesce(r.admin_total,0),0),total=greatest(coalesce(mb.food_total,0)-coalesce(r.food_total,0),0)+greatest(coalesce(mb.admin_added_total,0)-coalesce(r.admin_total,0),0),days_ordered=coalesce(v_days,0),updated_at=now() where mb.employee_id=r.employee_id and mb.canteen_id=v_canteen and mb.bill_month=r.bill_month and mb.bill_year=r.bill_year;end loop;end$$;
create or replace function public.admin_factory_reset() returns void language plpgsql security definer set search_path=public as $$declare v_canteen uuid:=public.current_canteen_id();begin if not public.is_admin_user() or v_canteen is null then raise exception 'Admin authorization required';end if;delete from public.order_items where canteen_id=v_canteen;delete from public.orders where canteen_id=v_canteen;delete from public.bill_payments where canteen_id=v_canteen;delete from public.monthly_bills where canteen_id=v_canteen;delete from public.payments where canteen_id=v_canteen;delete from public.employee_adjustments where canteen_id=v_canteen;delete from public.notifications where canteen_id=v_canteen;delete from public.daily_menu where canteen_id=v_canteen;delete from public.menu_prices where canteen_id=v_canteen;delete from public.holidays where canteen_id=v_canteen;delete from public.expenses where canteen_id=v_canteen;delete from public.profiles where canteen_id=v_canteen and id<>auth.uid() and role<>'admin';end$$;
create or replace function public.get_bill_payment_summary(p_bill_id uuid) returns table(current_total numeric,confirmed_received numeric,pending_amount numeric,outstanding_balance numeric,current_payment_id uuid) language sql security definer set search_path=public as $$select coalesce(mb.total,0),coalesce((select sum(amount) from public.bill_payments where bill_id=mb.id and employee_id=mb.employee_id and canteen_id=mb.canteen_id and status='paid'),0),coalesce((select sum(amount) from public.bill_payments where bill_id=mb.id and employee_id=mb.employee_id and canteen_id=mb.canteen_id and status='pending_verification'),0),greatest(coalesce(mb.total,0)-coalesce((select sum(amount) from public.bill_payments where bill_id=mb.id and employee_id=mb.employee_id and canteen_id=mb.canteen_id and status='paid'),0),0),(select id from public.bill_payments where bill_id=mb.id and employee_id=mb.employee_id and canteen_id=mb.canteen_id and status='pending_verification' order by created_at desc limit 1) from public.monthly_bills mb where mb.id=p_bill_id and mb.canteen_id=public.current_canteen_id() and(mb.employee_id=auth.uid() or public.is_admin_user())$$;
create or replace function public.confirm_bill_payment(p_bill_id uuid) returns bill_payments language plpgsql security definer set search_path=public as $$declare v_bill public.monthly_bills%rowtype;v_paid numeric:=0;v_pending public.bill_payments%rowtype;v_balance numeric:=0;v_payment public.bill_payments%rowtype;begin select * into v_bill from public.monthly_bills where id=p_bill_id and employee_id=auth.uid() and published=true and canteen_id=public.current_canteen_id();if not found then raise exception 'Bill not found or not accessible';end if;select coalesce(sum(amount),0) into v_paid from public.bill_payments where bill_id=p_bill_id and employee_id=auth.uid() and canteen_id=v_bill.canteen_id and status='paid';select * into v_pending from public.bill_payments where bill_id=p_bill_id and employee_id=auth.uid() and canteen_id=v_bill.canteen_id and status='pending_verification' order by created_at desc limit 1;if found then return v_pending;end if;v_balance:=greatest(coalesce(v_bill.total,0)-v_paid,0);if v_balance<=0 then raise exception 'No additional payment due';end if;insert into public.bill_payments(id,bill_id,employee_id,amount,status,confirmed_at,created_at,updated_at,canteen_id) values(gen_random_uuid(),p_bill_id,auth.uid(),v_balance,'pending_verification',now(),now(),now(),v_bill.canteen_id) returning * into v_payment;return v_payment;end$$;
create or replace function public.set_bill_payment_status(p_payment_id uuid,p_status text) returns bill_payments language plpgsql security definer set search_path=public as $$declare v_admin public.profiles%rowtype;v_payment public.bill_payments%rowtype;begin select * into v_admin from public.profiles where id=auth.uid() and role='admin' and status='active' and canteen_id=public.current_canteen_id();if not found then raise exception 'Admin authorization required';end if;if p_status not in('paid','not_received') then raise exception 'Invalid payment status';end if;select * into v_payment from public.bill_payments where id=p_payment_id and canteen_id=public.current_canteen_id();if not found then raise exception 'Payment record not found';end if;update public.bill_payments set status=p_status,approved_at=case when p_status='paid' then now() else null end,approved_by=case when p_status='paid' then auth.uid() else null end,updated_at=now() where id=p_payment_id returning * into v_payment;insert into public.notifications(recipient_id,notification_type,title,message,payload,created_at,canteen_id) values(v_payment.employee_id,'payment_status_updated',case when p_status='paid' then 'Payment Received' else 'Payment Not Received' end,case when p_status='paid' then 'Your payment has been verified as received.' else 'Your payment was not received. Please make the outstanding payment again.' end,jsonb_build_object('bill_id',v_payment.bill_id,'payment_id',v_payment.id,'status',p_status,'amount',v_payment.amount),now(),v_payment.canteen_id);return v_payment;end$$;
create or replace function public.snapshot_bill_upi() returns trigger language plpgsql security definer set search_path=public as $$declare s record;begin if new.upi_id is null or btrim(new.upi_id)='' then select upi_name,upi_id into s from public.payment_settings where canteen_id=new.canteen_id limit 1;new.upi_name:=coalesce(new.upi_name,s.upi_name);new.upi_id:=coalesce(new.upi_id,s.upi_id);end if;return new;end$$;
create or replace function public.cleanup_go_canteen_old_data() returns void language plpgsql security definer set search_path=public as $$declare cutoff_date date:=(date_trunc('month',current_date)-interval '2 months')::date;v_canteen uuid:=public.current_canteen_id();begin if not public.is_admin_user() then raise exception 'Admin authorization required';end if;delete from public.expenses where expense_date<cutoff_date and canteen_id=v_canteen;delete from public.order_items where canteen_id=v_canteen and order_id in(select id from public.orders where canteen_id=v_canteen and ordered_for<cutoff_date);delete from public.orders where canteen_id=v_canteen and ordered_for<cutoff_date;end$$;
create or replace function public.cleanup_old_canteen_history() returns void language plpgsql security definer set search_path=public as $$declare cutoff_date date:=(date_trunc('month',current_date)-interval '2 months')::date;v_canteen uuid:=public.current_canteen_id();begin if not public.is_admin_user() then raise exception 'Admin authorization required';end if;delete from public.expenses where expense_date<cutoff_date and canteen_id=v_canteen;delete from public.order_items where canteen_id=v_canteen and order_id in(select id from public.orders where canteen_id=v_canteen and ordered_for<cutoff_date);delete from public.orders where canteen_id=v_canteen and ordered_for<cutoff_date;end$$;
create or replace function public.purge_old_order_history() returns void language plpgsql security definer set search_path=public as $$declare cutoff_date date:=(date_trunc('month',current_date)-interval '2 months')::date;v_canteen uuid:=public.current_canteen_id();begin delete from public.order_items where canteen_id=v_canteen and order_id in(select id from public.orders where canteen_id=v_canteen and ordered_for<cutoff_date);delete from public.orders where canteen_id=v_canteen and ordered_for<cutoff_date;end$$;
notify pgrst,'reload schema';
